// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz the caller 'from', the callee address (we will supply a recorder contract),
    // the array length and values (we'll constrain length to be >0 to target the rule), and v
    function testFuzz_property(address from, uint8 len, uint256 v) public {
        // keep len in a reasonable bound but allow >0
        uint256 boundedLen = bound(len, 1, 6); // ensure at least one recipient to exercise the require

        // build a dynamic array of addresses to pass as _tos
        address[] memory tos = new address[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) {
            // derive addresses deterministically from inputs so fuzzer can vary them
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // deploy a recorder helper that will accept the low-level calls and record them
        Recorder rec = new Recorder();

        // the rule: for any non-empty _tos, the reference should NOT revert and returns true.
        // call and capture whether it reverted
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: for any non-empty _tos, the reference must not revert.
        // This will hold for the correct contract; the mutant that inverts the require will revert
        // for these inputs, making this assertion fail on the mutant for some fuzz cases.
        assertTrue(ok);
    }
}

// A minimal recording helper that exposes the transferFrom signature the contract encodes
// and records how many times it was called and the last arguments seen.
contract Recorder {
    uint public count;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    // match the selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        count += 1;
        lastFrom = from;
        lastTo = to;
        lastV = value;
        return true;
    }
}
